INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b5fa23c3-dbfc-547a-8288-ba6c82c614b2', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', $$Which spanning-tree protocol is the IEEE standard that converges faster than STP?$$::text, $$[{"id": "A", "text": "STP", "is_correct": false}, {"id": "B", "text": "RSTP", "is_correct": true}, {"id": "C", "text": "PVST+", "is_correct": false}, {"id": "D", "text": "MSTP", "is_correct": false}]$$::jsonb, $$RSTP (802.1w) is the IEEE standard that provides faster convergence than legacy STP (802.1D).$$::text, $${"https://www.juniper.net/us/en/training/certification/certification-tracks/jncip-ent.html"}$$::text[], $$Layer 2 Switching$$::text, 12.0, 'a45181f17d69894e', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ea81838a-a090-56b9-b116-a9fdb69ff761', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', $$Which feature should be enabled on switch access ports to immediately transition them to forwarding?$$::text, $$[{"id": "A", "text": "BPDU Guard", "is_correct": false}, {"id": "B", "text": "Root Guard", "is_correct": false}, {"id": "C", "text": "PortFast", "is_correct": true}, {"id": "D", "text": "Loop Guard", "is_correct": false}]$$::jsonb, $$PortFast allows access ports to skip listening and learning states and go directly to forwarding.$$::text, $${"https://www.juniper.net/us/en/training/certification/certification-tracks/jncip-ent.html"}$$::text[], $$Layer 2 Switching$$::text, 12.0, '9501c9aa6ae9ca1d', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('24730208-49d9-59e9-8398-f2431d87e7d4', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', $$Which protocol provides loop-free Layer 2 topology in a multi-vendor environment?$$::text, $$[{"id": "A", "text": "VTP", "is_correct": false}, {"id": "B", "text": "DTP", "is_correct": false}, {"id": "C", "text": "RSTP", "is_correct": true}, {"id": "D", "text": "PAgP", "is_correct": false}]$$::jsonb, $$RSTP/MSTP are IEEE standards for loop-free Layer 2. VTP manages VLANs, DTP negotiates trunks, PAgP is Cisco-proprietary.$$::text, $${"https://www.juniper.net/us/en/training/certification/certification-tracks/jncip-ent.html"}$$::text[], $$Layer 2 Switching$$::text, 12.0, '8cfaaadb9374a600', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8f90bdf0-067f-5928-8f2a-d1d7f599a7a8', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', $$Which Junos command configures an aggregated Ethernet interface with LACP?$$::text, $$[{"id": "A", "text": "set interfaces ae0 aggregated-ethernet lacp active", "is_correct": true}, {"id": "B", "text": "set interfaces ae0 ether-options 802.3ad", "is_correct": false}, {"id": "C", "text": "set interfaces ge-0/0/0 channel-group 1", "is_correct": false}, {"id": "D", "text": "set interfaces ae0 lacp enable", "is_correct": false}]$$::jsonb, $$In Junos, LACP is enabled on aggregated Ethernet interfaces with 'aggregated-ethernet-options lacp active'.$$::text, $${"https://www.juniper.net/us/en/training/certification/certification-tracks/jncip-ent.html"}$$::text[], $$Layer 2 Switching$$::text, 12.0, 'd63317d365d16f94', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('922edae2-f8ff-5f66-8fcc-08c151e37440', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', $$Which VLAN tagging protocol is an IEEE standard?$$::text, $$[{"id": "A", "text": "ISL", "is_correct": false}, {"id": "B", "text": "DTP", "is_correct": false}, {"id": "C", "text": "802.1Q", "is_correct": true}, {"id": "D", "text": "VTP", "is_correct": false}]$$::jsonb, $$802.1Q is the IEEE standard for VLAN tagging. ISL is Cisco-proprietary and deprecated.$$::text, $${"https://www.juniper.net/us/en/training/certification/certification-tracks/jncip-ent.html"}$$::text[], $$Layer 2 Switching$$::text, 12.0, 'bc4b14b24407a7c7', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('683a4c98-18cc-58c9-af11-6da2949dcfb6', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', $$What is the purpose of BPDU Guard?$$::text, $$[{"id": "A", "text": "To prevent root bridge changes", "is_correct": false}, {"id": "B", "text": "To disable PortFast ports that receive BPDUs", "is_correct": true}, {"id": "C", "text": "To block inferior BPDUs", "is_correct": false}, {"id": "D", "text": "To enable rapid convergence", "is_correct": false}]$$::jsonb, $$BPDU Guard protects PortFast ports by putting them in err-disabled state if they receive a BPDU.$$::text, $${"https://www.juniper.net/us/en/training/certification/certification-tracks/jncip-ent.html"}$$::text[], $$Layer 2 Switching$$::text, 12.0, '7fa22ff4661529d9', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4a09ead3-72ca-55b1-9ee8-7b7243719651', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', $$Which Junos command shows the Ethernet switching table?$$::text, $$[{"id": "A", "text": "show ethernet-switching table", "is_correct": true}, {"id": "B", "text": "show mac-address-table", "is_correct": false}, {"id": "C", "text": "show bridge table", "is_correct": false}, {"id": "D", "text": "show switching-table", "is_correct": false}]$$::jsonb, $$Junos uses 'show ethernet-switching table' to display MAC address learning on switching platforms.$$::text, $${"https://www.juniper.net/us/en/training/certification/certification-tracks/jncip-ent.html"}$$::text[], $$Layer 2 Switching$$::text, 12.0, '507b2cbbf5cbce21', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ea0c897f-b0f5-559e-a11e-b143a7856c05', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', $$Which OSPF area type can contain routes from multiple areas but does not originate external routes?$$::text, $$[{"id": "A", "text": "Standard area", "is_correct": false}, {"id": "B", "text": "Stub area", "is_correct": false}, {"id": "C", "text": "Totally stubby area", "is_correct": false}, {"id": "D", "text": "Backbone area", "is_correct": true}]$$::jsonb, $$Area 0 is the OSPF backbone. It connects all other areas and can contain inter-area and external routes.$$::text, $${"https://www.juniper.net/us/en/training/certification/certification-tracks/jncip-ent.html"}$$::text[], $$OSPF$$::text, 12.0, 'ec41a19c4fa4c9e1', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('011e03e8-831e-5853-a70b-c4d510f011a0', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', $$Which IS-IS level forms the backbone?$$::text, $$[{"id": "A", "text": "Level 1", "is_correct": false}, {"id": "B", "text": "Level 2", "is_correct": true}, {"id": "C", "text": "Level 1/2", "is_correct": false}, {"id": "D", "text": "Level 0", "is_correct": false}]$$::jsonb, $$IS-IS Level 2 routers form the backbone and know the full inter-area topology.$$::text, $${"https://www.juniper.net/us/en/training/certification/certification-tracks/jncip-ent.html"}$$::text[], $$IS-IS$$::text, 12.0, '2ae18e6dd5d22398', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('381f4bff-d598-594c-bf29-1e08fa869926', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', $$Which OSPF LSA type is generated by an ABR to advertise inter-area routes?$$::text, $$[{"id": "A", "text": "Type 1", "is_correct": false}, {"id": "B", "text": "Type 2", "is_correct": false}, {"id": "C", "text": "Type 3", "is_correct": true}, {"id": "D", "text": "Type 5", "is_correct": false}]$$::jsonb, $$Type 3 LSAs (summary LSAs) are originated by ABRs to advertise inter-area routes.$$::text, $${"https://www.juniper.net/us/en/training/certification/certification-tracks/jncip-ent.html"}$$::text[], $$OSPF$$::text, 12.0, '3e05d0ba743450f7', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e919645a-fbae-5981-8918-e922e545e70a', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', $$Which command displays IS-IS adjacencies on a Junos device?$$::text, $$[{"id": "A", "text": "show isis neighbors", "is_correct": false}, {"id": "B", "text": "show isis adjacency", "is_correct": true}, {"id": "C", "text": "show isis interface", "is_correct": false}, {"id": "D", "text": "show isis database", "is_correct": false}]$$::jsonb, $$'show isis adjacency' displays IS-IS neighbor adjacencies and their states.$$::text, $${"https://www.juniper.net/us/en/training/certification/certification-tracks/jncip-ent.html"}$$::text[], $$IS-IS$$::text, 12.0, '7058a77fa903ec0c', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f57efd7b-829b-5d53-be72-cd3a83f6277e', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', $$Which OSPF network type elects a DR/BDR?$$::text, $$[{"id": "A", "text": "Point-to-point", "is_correct": false}, {"id": "B", "text": "Broadcast", "is_correct": true}, {"id": "C", "text": "Point-to-multipoint", "is_correct": false}, {"id": "D", "text": "Loopback", "is_correct": false}]$$::jsonb, $$Broadcast and NBMA OSPF network types elect a DR/BDR to reduce adjacency count.$$::text, $${"https://www.juniper.net/us/en/training/certification/certification-tracks/jncip-ent.html"}$$::text[], $$OSPF$$::text, 12.0, '9890f28e91bd7f39', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('60237cd5-1d29-52b0-b26e-08dc23082920', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', $$Which BGP attribute is preferred when higher?$$::text, $$[{"id": "A", "text": "MED", "is_correct": false}, {"id": "B", "text": "AS Path length", "is_correct": false}, {"id": "C", "text": "Local Preference", "is_correct": true}, {"id": "D", "text": "Router ID", "is_correct": false}]$$::jsonb, $$Local Preference is preferred when higher. MED is preferred when lower, and shorter AS Path is preferred.$$::text, $${"https://www.juniper.net/us/en/training/certification/certification-tracks/jncip-ent.html"}$$::text[], $$BGP$$::text, 12.0, '0c0414077c38b258', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bf29fb8c-4e52-5a8b-9b36-dc2fe6b13bca', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', $$Which BGP feature allows a router to advertise multiple paths for the same prefix?$$::text, $$[{"id": "A", "text": "Add-path", "is_correct": true}, {"id": "B", "text": "Multipath", "is_correct": false}, {"id": "C", "text": "Route reflector", "is_correct": false}, {"id": "D", "text": "Confederation", "is_correct": false}]$$::jsonb, $$BGP add-path allows a router to advertise multiple paths for the same prefix to a peer.$$::text, $${"https://www.juniper.net/us/en/training/certification/certification-tracks/jncip-ent.html"}$$::text[], $$BGP$$::text, 12.0, '5ab69a03ad6a1022', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bd6b3500-54a7-57ae-ac13-37343110fe1e', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', $$Which Junos policy action sets the BGP local preference?$$::text, $$[{"id": "A", "text": "set local-preference 200", "is_correct": true}, {"id": "B", "text": "set preference 200", "is_correct": false}, {"id": "C", "text": "set metric 200", "is_correct": false}, {"id": "D", "text": "set as-path-prepend 200", "is_correct": false}]$$::jsonb, $$In Junos, 'set local-preference <value>' sets the BGP LOCAL_PREF attribute.$$::text, $${"https://www.juniper.net/us/en/training/certification/certification-tracks/jncip-ent.html"}$$::text[], $$BGP$$::text, 12.0, '64c486e2b40c4822', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('422904b5-53f0-581a-bcf4-f79f131bc093', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', $$What is the purpose of BGP confederations?$$::text, $$[{"id": "A", "text": "To encrypt BGP sessions", "is_correct": false}, {"id": "B", "text": "To divide a large AS into smaller sub-ASes to reduce iBGP mesh", "is_correct": true}, {"id": "C", "text": "To replace route reflectors", "is_correct": false}, {"id": "D", "text": "To aggregate routes", "is_correct": false}]$$::jsonb, $$BGP confederations split a large autonomous system into smaller sub-ASes, reducing the full-mesh iBGP requirement.$$::text, $${"https://www.juniper.net/us/en/training/certification/certification-tracks/jncip-ent.html"}$$::text[], $$BGP$$::text, 12.0, '8cf40961cb42b4ee', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('75099bba-1fd5-5a0f-b331-fb6e1f2d1586', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', $$Which PIM mode uses source trees only and does not require a rendezvous point?$$::text, $$[{"id": "A", "text": "PIM-SM", "is_correct": false}, {"id": "B", "text": "PIM-DM", "is_correct": false}, {"id": "C", "text": "PIM-SSM", "is_correct": true}, {"id": "D", "text": "Bidir-PIM", "is_correct": false}]$$::jsonb, $$PIM Source-Specific Mode (SSM) uses source trees only and does not require a rendezvous point.$$::text, $${"https://www.juniper.net/us/en/training/certification/certification-tracks/jncip-ent.html"}$$::text[], $$Multicast$$::text, 8.0, '89ed93af9fd41db8', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d2a86420-9aef-563a-bff2-ed1413f8cab3', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', $$Which IGMP version supports source-specific queries?$$::text, $$[{"id": "A", "text": "IGMPv1", "is_correct": false}, {"id": "B", "text": "IGMPv2", "is_correct": false}, {"id": "C", "text": "IGMPv3", "is_correct": true}, {"id": "D", "text": "IGMPv4", "is_correct": false}]$$::jsonb, $$IGMPv3 supports source-specific multicast (SSM) and source filtering.$$::text, $${"https://www.juniper.net/us/en/training/certification/certification-tracks/jncip-ent.html"}$$::text[], $$Multicast$$::text, 8.0, 'd1cea9aae8270ab9', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7b4cc7c2-02e8-570c-b35e-76c5319e65bf', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', $$Which Junos CoS component rewrites outgoing DSCP or IEEE 802.1p bits?$$::text, $$[{"id": "A", "text": "Classifier", "is_correct": false}, {"id": "B", "text": "Rewrite rule", "is_correct": true}, {"id": "C", "text": "Scheduler", "is_correct": false}, {"id": "D", "text": "Drop profile", "is_correct": false}]$$::jsonb, $$Rewrite rules modify outgoing packet markings such as DSCP or 802.1p.$$::text, $${"https://www.juniper.net/us/en/training/certification/certification-tracks/jncip-ent.html"}$$::text[], $$CoS$$::text, 8.0, '3be0ed5d28d46453', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f49c6ee5-818b-5586-b3de-93a2676ac1a6', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', $$Which EVPN route type is used for inclusive multicast Ethernet tag route?$$::text, $$[{"id": "A", "text": "Type 1", "is_correct": false}, {"id": "B", "text": "Type 2", "is_correct": false}, {"id": "C", "text": "Type 3", "is_correct": true}, {"id": "D", "text": "Type 4", "is_correct": false}]$$::jsonb, $$EVPN Type 3 routes are inclusive multicast routes used for broadcast, unknown unicast, and multicast flooding.$$::text, $${"https://www.juniper.net/us/en/training/certification/certification-tracks/jncip-ent.html"}$$::text[], $$EVPN$$::text, 8.0, '0dd0dc4e54ce78ec', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('069d5140-b071-5a0e-9b5b-855c6e7ba9b7', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', $$Which EVPN route type advertises Ethernet segment information for Designated Forwarder election?$$::text, $$[{"id": "A", "text": "Type 1", "is_correct": false}, {"id": "B", "text": "Type 2", "is_correct": false}, {"id": "C", "text": "Type 3", "is_correct": false}, {"id": "D", "text": "Type 4", "is_correct": true}]$$::jsonb, $$EVPN Type 4 routes advertise Ethernet segment information and are used for Designated Forwarder election.$$::text, $${"https://www.juniper.net/us/en/training/certification/certification-tracks/jncip-ent.html"}$$::text[], $$EVPN$$::text, 8.0, '6d40f7137647b608', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6b49c6a1-dd7c-5d8d-b221-a1c24b36b0a8', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', $$Which CoS feature shapes traffic by buffering excess instead of dropping it?$$::text, $$[{"id": "A", "text": "Policer", "is_correct": false}, {"id": "B", "text": "Shaper", "is_correct": true}, {"id": "C", "text": "Scheduler", "is_correct": false}, {"id": "D", "text": "Classifier", "is_correct": false}]$$::jsonb, $$Shapers buffer and smooth traffic to conform to a rate. Policers drop or remark excess traffic.$$::text, $${"https://www.juniper.net/us/en/training/certification/certification-tracks/jncip-ent.html"}$$::text[], $$CoS$$::text, 8.0, 'efbee9287117c88e', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8f4769e2-9f75-5a2d-bc6c-4927dd5bd232', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', $$Which spanning-tree mode allows multiple VLANs to share a single spanning-tree instance?$$::text, $$[{"id": "A", "text": "PVST+", "is_correct": false}, {"id": "B", "text": "RSTP", "is_correct": false}, {"id": "C", "text": "MSTP", "is_correct": true}, {"id": "D", "text": "STP", "is_correct": false}]$$::jsonb, $$MSTP (802.1s) maps multiple VLANs to multiple spanning-tree instances, reducing overhead compared to per-VLAN RSTP.$$::text, $${"https://www.juniper.net/us/en/training/certification/certification-tracks/jncip-ent.html"}$$::text[], $$Layer 2 Switching$$::text, 12.0, '8691e7a930ad585f', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4cd27d5c-b155-512a-9628-d2298394543c', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', $$Which command configures an access interface in VLAN 100 on a Junos EX switch?$$::text, $$[{"id": "A", "text": "set interfaces ge-0/0/0 unit 0 family ethernet-switching vlan members 100", "is_correct": true}, {"id": "B", "text": "set interfaces ge-0/0/0 switchport access vlan 100", "is_correct": false}, {"id": "C", "text": "set vlan 100 interface ge-0/0/0", "is_correct": false}, {"id": "D", "text": "set interfaces ge-0/0/0 vlan 100", "is_correct": false}]$$::jsonb, $$On Junos EX, access VLAN membership is configured under 'family ethernet-switching vlan members'.$$::text, $${"https://www.juniper.net/us/en/training/certification/certification-tracks/jncip-ent.html"}$$::text[], $$Layer 2 Switching$$::text, 12.0, '179829bfe5cbae97', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('031f9cf5-c1f4-5279-9620-36000d114095', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', $$Which feature protects against accidental BPDUs on PortFast-like edge ports in Junos?$$::text, $$[{"id": "A", "text": "BPDU Guard", "is_correct": true}, {"id": "B", "text": "Root Guard", "is_correct": false}, {"id": "C", "text": "Loop Guard", "is_correct": false}, {"id": "D", "text": "BPDU Filter", "is_correct": false}]$$::jsonb, $$BPDU Guard disables edge ports that receive BPDUs, preventing accidental switch connections.$$::text, $${"https://www.juniper.net/us/en/training/certification/certification-tracks/jncip-ent.html"}$$::text[], $$Layer 2 Switching$$::text, 12.0, '305cf8eb42f844e2', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bf628265-0fd2-5b29-b1e8-e5337f7fc6c4', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', $$Which protocol negotiates an aggregated Ethernet link between switches?$$::text, $$[{"id": "A", "text": "VRRP", "is_correct": false}, {"id": "B", "text": "LACP", "is_correct": true}, {"id": "C", "text": "RSTP", "is_correct": false}, {"id": "D", "text": "DTP", "is_correct": false}]$$::jsonb, $$LACP (Link Aggregation Control Protocol, 802.3ad) dynamically negotiates aggregated Ethernet links.$$::text, $${"https://www.juniper.net/us/en/training/certification/certification-tracks/jncip-ent.html"}$$::text[], $$Layer 2 Switching$$::text, 12.0, '0231a8bfa8a04eec', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ae8d9e26-73e4-550b-998f-d3b0d3b8ba41', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', $$Which Junos command shows the MAC learning table on an EX switch?$$::text, $$[{"id": "A", "text": "show ethernet-switching table", "is_correct": true}, {"id": "B", "text": "show mac-address-table", "is_correct": false}, {"id": "C", "text": "show bridge table", "is_correct": false}, {"id": "D", "text": "show switching-table", "is_correct": false}]$$::jsonb, $$'show ethernet-switching table' displays learned MAC addresses on Junos EX switches.$$::text, $${"https://www.juniper.net/us/en/training/certification/certification-tracks/jncip-ent.html"}$$::text[], $$Layer 2 Switching$$::text, 12.0, 'ef242e8234787404', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8c79d314-94ab-57ea-9587-bbdb416d23a8', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', $$Which feature provides default gateway redundancy using a virtual IP?$$::text, $$[{"id": "A", "text": "LACP", "is_correct": false}, {"id": "B", "text": "VRRP", "is_correct": true}, {"id": "C", "text": "RSTP", "is_correct": false}, {"id": "D", "text": "LLDP", "is_correct": false}]$$::jsonb, $$VRRP provides default gateway redundancy by sharing a virtual IP between routers.$$::text, $${"https://www.juniper.net/us/en/training/certification/certification-tracks/jncip-ent.html"}$$::text[], $$Layer 2 Switching$$::text, 12.0, '071cf7074f301b18', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ccf1f141-05a8-5f60-9a2e-a4db0559cc6d', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', $$Which STP guard prevents a port from becoming the root port?$$::text, $$[{"id": "A", "text": "BPDU Guard", "is_correct": false}, {"id": "B", "text": "Root Guard", "is_correct": true}, {"id": "C", "text": "Loop Guard", "is_correct": false}, {"id": "D", "text": "Storm Control", "is_correct": false}]$$::jsonb, $$Root Guard prevents a port from accepting superior BPDUs and becoming a root port.$$::text, $${"https://www.juniper.net/us/en/training/certification/certification-tracks/jncip-ent.html"}$$::text[], $$Layer 2 Switching$$::text, 12.0, 'ec2a6dc3789e47ff', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f7ef8e95-b36b-50c8-ae27-9e4336852c91', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', $$Which protocol advertises device identity and capabilities between directly connected neighbors?$$::text, $$[{"id": "A", "text": "CDP", "is_correct": false}, {"id": "B", "text": "LLDP", "is_correct": true}, {"id": "C", "text": "VTP", "is_correct": false}, {"id": "D", "text": "DTP", "is_correct": false}]$$::jsonb, $$LLDP (Link Layer Discovery Protocol) is an IEEE standard for neighbor discovery. CDP is Cisco-proprietary.$$::text, $${"https://www.juniper.net/us/en/training/certification/certification-tracks/jncip-ent.html"}$$::text[], $$Layer 2 Switching$$::text, 12.0, '30c7bb6443a72bf0', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1ca53d36-fa9b-57a2-9450-da266db312de', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', $$Which command configures a trunk interface carrying VLANs 10-20 on Junos EX?$$::text, $$[{"id": "A", "text": "set interfaces ge-0/0/0 unit 0 family ethernet-switching interface-mode trunk vlan members 10-20", "is_correct": true}, {"id": "B", "text": "set interfaces ge-0/0/0 switchport mode trunk allowed-vlan 10-20", "is_correct": false}, {"id": "C", "text": "set interfaces ge-0/0/0 trunk vlan 10-20", "is_correct": false}, {"id": "D", "text": "set vlan trunk 10-20 interface ge-0/0/0", "is_correct": false}]$$::jsonb, $$Junos EX trunk configuration uses 'interface-mode trunk' and 'vlan members' under ethernet-switching.$$::text, $${"https://www.juniper.net/us/en/training/certification/certification-tracks/jncip-ent.html"}$$::text[], $$Layer 2 Switching$$::text, 12.0, 'f0c16887ca56e4ea', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bc2fee1e-4eac-5fbe-977a-22f2a78cbdf4', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', $$Which spanning-tree state in RSTP discards frames but listens for BPDUs?$$::text, $$[{"id": "A", "text": "Discarding", "is_correct": true}, {"id": "B", "text": "Blocking", "is_correct": false}, {"id": "C", "text": "Listening", "is_correct": false}, {"id": "D", "text": "Learning", "is_correct": false}]$$::jsonb, $$RSTP uses Discarding state, which combines legacy Blocking and Listening states.$$::text, $${"https://www.juniper.net/us/en/training/certification/certification-tracks/jncip-ent.html"}$$::text[], $$Layer 2 Switching$$::text, 12.0, '86662826b95ae23c', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cea89a47-f673-502e-9f7f-4b5a85761909', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'remember', $$Which OSPF LSA type describes routes to ASBRs?$$::text, $$[{"id": "A", "text": "Type 1", "is_correct": false}, {"id": "B", "text": "Type 2", "is_correct": false}, {"id": "C", "text": "Type 3", "is_correct": false}, {"id": "D", "text": "Type 4", "is_correct": true}]$$::jsonb, $$Type 4 Summary ASBR-LSAs describe the location of ASBRs to other areas.$$::text, $${"https://www.juniper.net/us/en/training/certification/certification-tracks/jncip-ent.html"}$$::text[], $$OSPF$$::text, 12.0, 'adf062edd8c8aebe', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('96ae872c-9e30-52e8-9078-2e04c8d9eefb', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', $$Which OSPF network type requires manual neighbor configuration?$$::text, $$[{"id": "A", "text": "Broadcast", "is_correct": false}, {"id": "B", "text": "Point-to-point", "is_correct": false}, {"id": "C", "text": "NBMA", "is_correct": true}, {"id": "D", "text": "Multi-access", "is_correct": false}]$$::jsonb, $$Non-Broadcast Multi-Access (NBMA) OSPF network types require manual neighbor statements.$$::text, $${"https://www.juniper.net/us/en/training/certification/certification-tracks/jncip-ent.html"}$$::text[], $$OSPF$$::text, 12.0, '44153b307ac7a8a6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0a1964c6-47fb-50c7-aa9e-e891f197b805', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', $$Which command enables IS-IS on an interface in Junos?$$::text, $$[{"id": "A", "text": "set protocols isis interface ge-0/0/0", "is_correct": true}, {"id": "B", "text": "set isis interface ge-0/0/0", "is_correct": false}, {"id": "C", "text": "set protocols isis enable ge-0/0/0", "is_correct": false}, {"id": "D", "text": "set interface ge-0/0/0 isis", "is_correct": false}]$$::jsonb, $$'set protocols isis interface <name>' enables IS-IS on the specified interface.$$::text, $${"https://www.juniper.net/us/en/training/certification/certification-tracks/jncip-ent.html"}$$::text[], $$IS-IS$$::text, 12.0, '83c4cc13c8b912d1', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1fa30535-46a9-5054-952c-017a2f619466', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', $$Which OSPF area accepts external routes as Type 7 LSAs?$$::text, $$[{"id": "A", "text": "Stub", "is_correct": false}, {"id": "B", "text": "Totally stubby", "is_correct": false}, {"id": "C", "text": "NSSA", "is_correct": true}, {"id": "D", "text": "Standard", "is_correct": false}]$$::jsonb, $$NSSA areas allow external routes to be advertised as Type 7 LSAs, converted to Type 5 at the ABR.$$::text, $${"https://www.juniper.net/us/en/training/certification/certification-tracks/jncip-ent.html"}$$::text[], $$OSPF$$::text, 12.0, '2da3d86dab6dc3e0', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('433e3361-2561-5a69-a1ae-0eee04bfe4a3', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', $$Which IS-IS metric style is required for IPv6 routing?$$::text, $$[{"id": "A", "text": "Narrow", "is_correct": false}, {"id": "B", "text": "Wide", "is_correct": true}, {"id": "C", "text": "Old", "is_correct": false}, {"id": "D", "text": "Legacy", "is_correct": false}]$$::jsonb, $$Wide metrics are required for IS-IS multi-topology and IPv6 support.$$::text, $${"https://www.juniper.net/us/en/training/certification/certification-tracks/jncip-ent.html"}$$::text[], $$IS-IS$$::text, 12.0, '89dda6b350088026', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b7341967-e62f-5eeb-afa9-bc34af8498cb', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', $$Which BGP attribute is used to prevent routing loops within an AS?$$::text, $$[{"id": "A", "text": "AS Path", "is_correct": true}, {"id": "B", "text": "Local Preference", "is_correct": false}, {"id": "C", "text": "MED", "is_correct": false}, {"id": "D", "text": "Origin", "is_correct": false}]$$::jsonb, $$The AS Path attribute lists ASes a route has traversed; routers discard routes containing their own AS number.$$::text, $${"https://www.juniper.net/us/en/training/certification/certification-tracks/jncip-ent.html"}$$::text[], $$BGP$$::text, 12.0, '4311cc34248587de', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a71511e1-bb8a-5ef5-bbcf-e959f74e7677', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', $$Which command displays BGP routes filtered by a specific community?$$::text, $$[{"id": "A", "text": "show route community <community>", "is_correct": true}, {"id": "B", "text": "show bgp community", "is_correct": false}, {"id": "C", "text": "show route protocol bgp community", "is_correct": false}, {"id": "D", "text": "show bgp routes community", "is_correct": false}]$$::jsonb, $$'show route community <community>' displays routes matching a specific BGP community.$$::text, $${"https://www.juniper.net/us/en/training/certification/certification-tracks/jncip-ent.html"}$$::text[], $$BGP$$::text, 12.0, 'e30b1abe23535cb5', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8a9e4acc-6627-5b41-8f07-819ab9f47418', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', $$Which BGP community prevents a route from being advertised outside the local AS?$$::text, $$[{"id": "A", "text": "no-export", "is_correct": true}, {"id": "B", "text": "no-advertise", "is_correct": false}, {"id": "C", "text": "internet", "is_correct": false}, {"id": "D", "text": "local-AS", "is_correct": false}]$$::jsonb, $$The no-export community prevents a route from being advertised to eBGP peers outside the local AS.$$::text, $${"https://www.juniper.net/us/en/training/certification/certification-tracks/jncip-ent.html"}$$::text[], $$BGP$$::text, 12.0, 'e390f1340beeeb4a', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6fbef42e-744a-5a33-a452-6e7d969b8dd0', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', $$Which BGP feature reduces iBGP full-mesh requirement?$$::text, $$[{"id": "A", "text": "Route reflector", "is_correct": true}, {"id": "B", "text": "Confederation", "is_correct": false}, {"id": "C", "text": "Add-path", "is_correct": false}, {"id": "D", "text": "Damping", "is_correct": false}]$$::jsonb, $$Route reflectors allow iBGP clients to peer only with the reflector, reducing full-mesh requirements.$$::text, $${"https://www.juniper.net/us/en/training/certification/certification-tracks/jncip-ent.html"}$$::text[], $$BGP$$::text, 12.0, '45e2d987d3c773ae', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e4a51c33-32d1-5e69-98a0-72a686fedfc6', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', $$Which Junos policy action sets the BGP community?$$::text, $$[{"id": "A", "text": "set community <name>", "is_correct": true}, {"id": "B", "text": "set bgp-community", "is_correct": false}, {"id": "C", "text": "add community", "is_correct": false}, {"id": "D", "text": "write community", "is_correct": false}]$$::jsonb, $$'set community <name>' adds or sets a BGP community in a Junos routing policy.$$::text, $${"https://www.juniper.net/us/en/training/certification/certification-tracks/jncip-ent.html"}$$::text[], $$BGP$$::text, 12.0, 'e9c2a5e60297d4ef', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('38f2d716-4108-5745-898b-da504d96332f', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', $$Which PIM mode requires a rendezvous point?$$::text, $$[{"id": "A", "text": "PIM-SM", "is_correct": true}, {"id": "B", "text": "PIM-DM", "is_correct": false}, {"id": "C", "text": "PIM-SSM", "is_correct": false}, {"id": "D", "text": "None", "is_correct": false}]$$::jsonb, $$PIM Sparse Mode requires a rendezvous point for sources and receivers to discover each other.$$::text, $${"https://www.juniper.net/us/en/training/certification/certification-tracks/jncip-ent.html"}$$::text[], $$Multicast$$::text, 8.0, '7f393467361b41fd', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9852edcc-b65c-5504-a26f-1c15a2e313a6', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', $$Which CoS component classifies incoming traffic into forwarding classes?$$::text, $$[{"id": "A", "text": "Classifier", "is_correct": true}, {"id": "B", "text": "Rewrite rule", "is_correct": false}, {"id": "C", "text": "Scheduler", "is_correct": false}, {"id": "D", "text": "Shaper", "is_correct": false}]$$::jsonb, $$Classifiers examine incoming packets and assign them to forwarding classes based on DSCP, 802.1p, etc.$$::text, $${"https://www.juniper.net/us/en/training/certification/certification-tracks/jncip-ent.html"}$$::text[], $$CoS$$::text, 8.0, '2ba41a6dcca2c230', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ca52c213-6178-5263-8e15-c7d156966083', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'remember', $$Which EVPN route type is used for auto-discovery per ES?$$::text, $$[{"id": "A", "text": "Type 1", "is_correct": true}, {"id": "B", "text": "Type 2", "is_correct": false}, {"id": "C", "text": "Type 3", "is_correct": false}, {"id": "D", "text": "Type 4", "is_correct": false}]$$::jsonb, $$EVPN Type 1 routes are Ethernet Auto-Discovery (A-D) routes per Ethernet Segment.$$::text, $${"https://www.juniper.net/us/en/training/certification/certification-tracks/jncip-ent.html"}$$::text[], $$EVPN$$::text, 8.0, '1595ebe065efe0a3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8cacb3fa-6d74-536a-95df-2318a709bace', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', $$Which feature prevents BUM traffic loops in EVPN multihoming?$$::text, $$[{"id": "A", "text": "Split horizon", "is_correct": true}, {"id": "B", "text": "STP", "is_correct": false}, {"id": "C", "text": "VRRP", "is_correct": false}, {"id": "D", "text": "LACP", "is_correct": false}]$$::jsonb, $$EVPN split horizon prevents broadcast, unknown unicast, and multicast traffic from being looped back to the same ES.$$::text, $${"https://www.juniper.net/us/en/training/certification/certification-tracks/jncip-ent.html"}$$::text[], $$EVPN$$::text, 8.0, 'b4c78184a22e2c7a', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e09fbd83-93fd-5f05-a3a2-9eb33c72381c', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', $$Which command shows the OSPF neighbor state on a Junos device?$$::text, $$[{"id": "A", "text": "show ospf neighbor", "is_correct": true}, {"id": "B", "text": "show ospf interface", "is_correct": false}, {"id": "C", "text": "show ospf database", "is_correct": false}, {"id": "D", "text": "show route ospf", "is_correct": false}]$$::jsonb, $$'show ospf neighbor' displays OSPF neighbor adjacencies, states, and DR/BDR information.$$::text, $${"https://www.juniper.net/us/en/training/certification/certification-tracks/jncip-ent.html"}$$::text[], $$Troubleshooting$$::text, 5.0, '26f1b393d8eacce0', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7f411f73-3ff6-51b6-8d54-1e3ac1268da5', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', $$Which command displays the current candidate configuration?$$::text, $$[{"id": "A", "text": "show", "is_correct": true}, {"id": "B", "text": "show configuration", "is_correct": false}, {"id": "C", "text": "show config", "is_correct": false}, {"id": "D", "text": "display config", "is_correct": false}]$$::jsonb, $$In configuration mode, 'show' displays the candidate configuration. 'show configuration' displays the active configuration.$$::text, $${"https://www.juniper.net/us/en/training/certification/certification-tracks/jncip-ent.html"}$$::text[], $$Troubleshooting$$::text, 5.0, '9106427295ff9cb0', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4b64e6f6-60a5-5368-bab5-71d2c89e4feb', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', $$Which command compares the candidate config with the active config?$$::text, $$[{"id": "A", "text": "show | compare", "is_correct": true}, {"id": "B", "text": "show diff", "is_correct": false}, {"id": "C", "text": "compare configuration", "is_correct": false}, {"id": "D", "text": "show configuration diff", "is_correct": false}]$$::jsonb, $$'show | compare' displays differences between the candidate and active configurations.$$::text, $${"https://www.juniper.net/us/en/training/certification/certification-tracks/jncip-ent.html"}$$::text[], $$Troubleshooting$$::text, 5.0, 'b1eb7ea25b134e71', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('527d50fe-1a60-52a8-8d31-441d55faa252', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', $$Which command reloads the factory-default configuration?$$::text, $$[{"id": "A", "text": "load factory-default", "is_correct": true}, {"id": "B", "text": "set factory-default", "is_correct": false}, {"id": "C", "text": "request system factory-default", "is_correct": false}, {"id": "D", "text": "reset configuration", "is_correct": false}]$$::jsonb, $$'load factory-default' replaces the candidate configuration with the factory-default configuration.$$::text, $${"https://www.juniper.net/us/en/training/certification/certification-tracks/jncip-ent.html"}$$::text[], $$Troubleshooting$$::text, 5.0, '4ff1174d7538d990', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d8b83719-b665-5d85-a5f9-c252051e99cb', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', $$Which command displays interface input/output errors?$$::text, $$[{"id": "A", "text": "show interfaces extensive", "is_correct": true}, {"id": "B", "text": "show interfaces terse", "is_correct": false}, {"id": "C", "text": "show interface errors", "is_correct": false}, {"id": "D", "text": "show chassis fpc", "is_correct": false}]$$::jsonb, $$'show interfaces extensive' displays detailed statistics including input/output errors.$$::text, $${"https://www.juniper.net/us/en/training/certification/certification-tracks/jncip-ent.html"}$$::text[], $$Troubleshooting$$::text, 5.0, '7d837323591b6881', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('61706224-7c89-54cf-8559-7883d31d3859', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', $$Which command shows active users and their login methods?$$::text, $$[{"id": "A", "text": "show system users", "is_correct": true}, {"id": "B", "text": "show users", "is_correct": false}, {"id": "C", "text": "show login users", "is_correct": false}, {"id": "D", "text": "show who", "is_correct": false}]$$::jsonb, $$'show system users' displays currently logged-in users, their TTYs, and login times.$$::text, $${"https://www.juniper.net/us/en/training/certification/certification-tracks/jncip-ent.html"}$$::text[], $$Troubleshooting$$::text, 5.0, 'c853bc831257a972', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('09771bd8-682c-5dde-a91d-79889973d6ee', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', $$Which command tests Layer 3 reachability with IPv6 on modern Junos?$$::text, $$[{"id": "A", "text": "ping", "is_correct": true}, {"id": "B", "text": "ping6", "is_correct": false}, {"id": "C", "text": "traceroute6", "is_correct": false}, {"id": "D", "text": "telnet", "is_correct": false}]$$::jsonb, $$Modern Junos supports 'ping' with both IPv4 and IPv6 destinations. Older platforms used 'ping6'.$$::text, $${"https://www.juniper.net/us/en/training/certification/certification-tracks/jncip-ent.html"}$$::text[], $$Troubleshooting$$::text, 5.0, 'a9e7bb818203e6ac', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8f532239-5ea1-5bd3-84ea-2a2d6f0e879a', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', $$Which command shows the active configuration in set format?$$::text, $$[{"id": "A", "text": "show configuration | display set", "is_correct": true}, {"id": "B", "text": "show | display set", "is_correct": false}, {"id": "C", "text": "show config set", "is_correct": false}, {"id": "D", "text": "display set", "is_correct": false}]$$::jsonb, $$'show configuration | display set' outputs the active configuration as set commands.$$::text, $${"https://www.juniper.net/us/en/training/certification/certification-tracks/jncip-ent.html"}$$::text[], $$Troubleshooting$$::text, 5.0, '11055065b6410a61', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('aaeee8c7-2af6-5d4e-90a6-84143ab1d814', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', $$Which command displays system uptime and load averages?$$::text, $$[{"id": "A", "text": "show system uptime", "is_correct": true}, {"id": "B", "text": "show version", "is_correct": false}, {"id": "C", "text": "show chassis routing-engine", "is_correct": false}, {"id": "D", "text": "show system statistics", "is_correct": false}]$$::jsonb, $$'show system uptime' displays current time, uptime, and load averages.$$::text, $${"https://www.juniper.net/us/en/training/certification/certification-tracks/jncip-ent.html"}$$::text[], $$Troubleshooting$$::text, 5.0, '68db6912d8721362', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('820d371c-325e-5238-bb8d-395c12a38c70', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', $$Which protocol allows a Layer 2 VLAN to span across a Layer 3 network?$$::text, $$[{"id": "A", "text": "VTP", "is_correct": false}, {"id": "B", "text": "VXLAN", "is_correct": true}, {"id": "C", "text": "RSTP", "is_correct": false}, {"id": "D", "text": "LACP", "is_correct": false}]$$::jsonb, $$VXLAN encapsulates Layer 2 frames in UDP packets, allowing Layer 2 segments to span Layer 3 networks.$$::text, $${"https://www.juniper.net/us/en/training/certification/certification-tracks/jncip-ent.html"}$$::text[], $$Layer 2 Switching$$::text, 12.0, '13a7fb5a82beeb55', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('45ddde81-39f7-5fe9-9231-d524e9ce2cea', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', $$Which feature on Junos EX switches limits broadcast traffic rate?$$::text, $$[{"id": "A", "text": "BPDU Guard", "is_correct": false}, {"id": "B", "text": "Storm control", "is_correct": true}, {"id": "C", "text": "Root Guard", "is_correct": false}, {"id": "D", "text": "Port security", "is_correct": false}]$$::jsonb, $$Storm control limits the rate of broadcast, multicast, and unknown unicast traffic on switch interfaces.$$::text, $${"https://www.juniper.net/us/en/training/certification/certification-tracks/jncip-ent.html"}$$::text[], $$Layer 2 Switching$$::text, 12.0, '2aff750b7576a91c', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('00990cfb-25c7-5054-ad3d-9a976300da99', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', $$Which command shows the ARP table on a Junos router?$$::text, $$[{"id": "A", "text": "show arp", "is_correct": true}, {"id": "B", "text": "show route arp", "is_correct": false}, {"id": "C", "text": "show interface arp", "is_correct": false}, {"id": "D", "text": "show system arp", "is_correct": false}]$$::jsonb, $$'show arp' displays the IPv4 address-to-MAC mapping table.$$::text, $${"https://www.juniper.net/us/en/training/certification/certification-tracks/jncip-ent.html"}$$::text[], $$Troubleshooting$$::text, 5.0, 'c487d9e597d4c26c', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8b2857d5-2954-5f54-89a5-3dfd04d1c632', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', $$Which Junos command shows the IPv6 neighbor table?$$::text, $$[{"id": "A", "text": "show ipv6 neighbors", "is_correct": true}, {"id": "B", "text": "show arp", "is_correct": false}, {"id": "C", "text": "show route ipv6", "is_correct": false}, {"id": "D", "text": "show ipv6 route", "is_correct": false}]$$::jsonb, $$'show ipv6 neighbors' displays IPv6 neighbor discovery entries, equivalent to ARP for IPv4.$$::text, $${"https://www.juniper.net/us/en/training/certification/certification-tracks/jncip-ent.html"}$$::text[], $$Troubleshooting$$::text, 5.0, '5806e2de5385b0eb', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c1c6abff-d3c8-58b6-a5e6-d6ef547b11c2', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', $$Which OSPF cost formula is used by Junos?$$::text, $$[{"id": "A", "text": "reference-bandwidth / interface-bandwidth", "is_correct": true}, {"id": "B", "text": "10^8 / interface-bandwidth", "is_correct": false}, {"id": "C", "text": "interface-bandwidth / reference-bandwidth", "is_correct": false}, {"id": "D", "text": "100 / interface-bandwidth", "is_correct": false}]$$::jsonb, $$Junos OSPF cost = reference-bandwidth / interface-bandwidth. The default reference bandwidth should be adjusted for high-speed links.$$::text, $${"https://www.juniper.net/us/en/training/certification/certification-tracks/jncip-ent.html"}$$::text[], $$OSPF$$::text, 12.0, '0c6777b2d4206e20', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d71956d9-4613-56ba-82d5-1d3e9a776baf', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', $$Which IS-IS PDU is sent periodically to maintain adjacencies?$$::text, $$[{"id": "A", "text": "LSP", "is_correct": false}, {"id": "B", "text": "CSNP", "is_correct": false}, {"id": "C", "text": "PSNP", "is_correct": false}, {"id": "D", "text": "IIH", "is_correct": true}]$$::jsonb, $$IS-IS Hello PDUs (IIH) are sent periodically to discover and maintain adjacencies.$$::text, $${"https://www.juniper.net/us/en/training/certification/certification-tracks/jncip-ent.html"}$$::text[], $$IS-IS$$::text, 12.0, '27147203c54c78a7', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3c433c00-cd0a-51f0-94d1-9abbf47228b0', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', $$Which command displays the IS-IS topology?$$::text, $$[{"id": "A", "text": "show isis topology", "is_correct": true}, {"id": "B", "text": "show isis route", "is_correct": false}, {"id": "C", "text": "show isis database", "is_correct": false}, {"id": "D", "text": "show isis adjacency", "is_correct": false}]$$::jsonb, $$'show isis topology' displays the IS-IS shortest-path tree and topology.$$::text, $${"https://www.juniper.net/us/en/training/certification/certification-tracks/jncip-ent.html"}$$::text[], $$IS-IS$$::text, 12.0, '350a819ff3474e58', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2653d04c-a7b2-5434-9403-4ae5e63626d1', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', $$Which BGP attribute is modified by the 'as-path-prepend' action?$$::text, $$[{"id": "A", "text": "AS Path", "is_correct": true}, {"id": "B", "text": "Origin", "is_correct": false}, {"id": "C", "text": "MED", "is_correct": false}, {"id": "D", "text": "Local Preference", "is_correct": false}]$$::jsonb, $$'as-path-prepend' adds AS numbers to the AS Path attribute, making a route less preferred.$$::text, $${"https://www.juniper.net/us/en/training/certification/certification-tracks/jncip-ent.html"}$$::text[], $$BGP$$::text, 12.0, '810ce1410c8313b2', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9d595a32-6592-55e2-bfa3-3abab1ab9a4a', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', $$Which command displays routes advertised to a BGP peer?$$::text, $$[{"id": "A", "text": "show route advertising-protocol bgp <peer>", "is_correct": true}, {"id": "B", "text": "show route receive-protocol bgp <peer>", "is_correct": false}, {"id": "C", "text": "show bgp neighbor <peer> routes", "is_correct": false}, {"id": "D", "text": "show route protocol bgp", "is_correct": false}]$$::jsonb, $$'show route advertising-protocol bgp <peer>' displays routes sent to a BGP peer.$$::text, $${"https://www.juniper.net/us/en/training/certification/certification-tracks/jncip-ent.html"}$$::text[], $$BGP$$::text, 12.0, 'ec29a73b19293967', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3ec8fa33-595d-515a-beaa-7c1abfd0facb', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', $$Which PIM mode is best suited for one-to-many streaming with known sources?$$::text, $$[{"id": "A", "text": "PIM-DM", "is_correct": false}, {"id": "B", "text": "PIM-SM", "is_correct": false}, {"id": "C", "text": "PIM-SSM", "is_correct": true}, {"id": "D", "text": "Bidir-PIM", "is_correct": false}]$$::jsonb, $$PIM-SSM is ideal for one-to-many streaming where receivers know the source and no RP is needed.$$::text, $${"https://www.juniper.net/us/en/training/certification/certification-tracks/jncip-ent.html"}$$::text[], $$Multicast$$::text, 8.0, '2ad196297feee5a1', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a299ae7f-d806-5b4c-8b14-d3bbe181558e', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', $$Which EVPN route type carries MAC/IP advertisements?$$::text, $$[{"id": "A", "text": "Type 1", "is_correct": false}, {"id": "B", "text": "Type 2", "is_correct": true}, {"id": "C", "text": "Type 3", "is_correct": false}, {"id": "D", "text": "Type 4", "is_correct": false}]$$::jsonb, $$EVPN Type 2 routes advertise MAC and IP reachability.$$::text, $${"https://www.juniper.net/us/en/training/certification/certification-tracks/jncip-ent.html"}$$::text[], $$EVPN$$::text, 8.0, 'eaac0bee6bddc329', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d14af314-3e96-5a9f-b3d6-3ee75b913b58', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', $$Which CoS component drops packets based on drop probability profiles?$$::text, $$[{"id": "A", "text": "Scheduler", "is_correct": false}, {"id": "B", "text": "Drop profile", "is_correct": true}, {"id": "C", "text": "Rewrite rule", "is_correct": false}, {"id": "D", "text": "Classifier", "is_correct": false}]$$::jsonb, $$Drop profiles define how aggressively packets are dropped based on queue fill level.$$::text, $${"https://www.juniper.net/us/en/training/certification/certification-tracks/jncip-ent.html"}$$::text[], $$CoS$$::text, 8.0, 'fbafc04807274c92', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('295eb4ce-156b-5ab1-8e40-05361c69c5ad', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', $$Which command shows the current active configuration?$$::text, $$[{"id": "A", "text": "show configuration", "is_correct": true}, {"id": "B", "text": "show", "is_correct": false}, {"id": "C", "text": "show config", "is_correct": false}, {"id": "D", "text": "display configuration", "is_correct": false}]$$::jsonb, $$'show configuration' displays the active configuration in operational mode. In config mode, 'show' shows the candidate.$$::text, $${"https://www.juniper.net/us/en/training/certification/certification-tracks/jncip-ent.html"}$$::text[], $$Troubleshooting$$::text, 5.0, '3d5dd7963e1af728', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3214cf5c-0ce6-501a-8e9b-92a8e9b61d20', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', $$Which command saves the current active configuration as rescue configuration?$$::text, $$[{"id": "A", "text": "request system configuration rescue save", "is_correct": true}, {"id": "B", "text": "save rescue", "is_correct": false}, {"id": "C", "text": "commit rescue", "is_correct": false}, {"id": "D", "text": "load rescue", "is_correct": false}]$$::jsonb, $$'request system configuration rescue save' saves the active configuration as the rescue configuration.$$::text, $${"https://www.juniper.net/us/en/training/certification/certification-tracks/jncip-ent.html"}$$::text[], $$Troubleshooting$$::text, 5.0, '605b3a2b63a7d0a9', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c7e7f346-70a3-5d61-99ac-c0a7ede63f40', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', $$Which command displays the routing engine CPU and memory usage?$$::text, $$[{"id": "A", "text": "show chassis routing-engine", "is_correct": true}, {"id": "B", "text": "show system processes", "is_correct": false}, {"id": "C", "text": "show route summary", "is_correct": false}, {"id": "D", "text": "show system memory", "is_correct": false}]$$::jsonb, $$'show chassis routing-engine' displays RE CPU, memory, and uptime.$$::text, $${"https://www.juniper.net/us/en/training/certification/certification-tracks/jncip-ent.html"}$$::text[], $$Troubleshooting$$::text, 5.0, '646d30077532dec8', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b63bdcf4-a69d-5cbd-9ed0-dc286d59b849', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', $$Which command enables real-time monitoring of interface statistics?$$::text, $$[{"id": "A", "text": "monitor interface", "is_correct": true}, {"id": "B", "text": "show interfaces extensive", "is_correct": false}, {"id": "C", "text": "watch interface", "is_correct": false}, {"id": "D", "text": "show interface monitor", "is_correct": false}]$$::jsonb, $$'monitor interface' provides real-time interface statistics, similar to top.$$::text, $${"https://www.juniper.net/us/en/training/certification/certification-tracks/jncip-ent.html"}$$::text[], $$Troubleshooting$$::text, 5.0, '59ac0bca2d32ffd5', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('600b2fe5-a6dc-5846-a0c1-43c5b5e0a49d', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', $$Which command captures packets on a Junos interface?$$::text, $$[{"id": "A", "text": "monitor traffic", "is_correct": true}, {"id": "B", "text": "capture packets", "is_correct": false}, {"id": "C", "text": "show traffic", "is_correct": false}, {"id": "D", "text": "trace traffic", "is_correct": false}]$$::jsonb, $$'monitor traffic interface <name>' captures packets on an interface.$$::text, $${"https://www.juniper.net/us/en/training/certification/certification-tracks/jncip-ent.html"}$$::text[], $$Troubleshooting$$::text, 5.0, 'cd29adbfb57c5909', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('daf93c13-f492-5f46-a75b-a089464e5747', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', $$Which Junos feature applies a common configuration to multiple interfaces?$$::text, $$[{"id": "A", "text": "Apply-groups", "is_correct": true}, {"id": "B", "text": "Configuration templates", "is_correct": false}, {"id": "C", "text": "Macros", "is_correct": false}, {"id": "D", "text": "Variables", "is_correct": false}]$$::jsonb, $$Apply-groups let you define a common configuration and apply it to multiple hierarchies.$$::text, $${"https://www.juniper.net/us/en/training/certification/certification-tracks/jncip-ent.html"}$$::text[], $$Troubleshooting$$::text, 5.0, 'd67e6e0c39b20f83', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5c788a7f-37ca-5dfc-9042-83815cf6fa2f', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', $$Which command rolls back to the previous committed configuration?$$::text, $$[{"id": "A", "text": "rollback 1", "is_correct": true}, {"id": "B", "text": "rollback 0", "is_correct": false}, {"id": "C", "text": "revert 1", "is_correct": false}, {"id": "D", "text": "undo commit", "is_correct": false}]$$::jsonb, $$'rollback 1' loads the previous committed configuration as the candidate. 'rollback 0' loads the current active config.$$::text, $${"https://www.juniper.net/us/en/training/certification/certification-tracks/jncip-ent.html"}$$::text[], $$Troubleshooting$$::text, 5.0, '790f3d02be132a24', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('26b88170-a31d-5a94-be5d-8a3b5ee72b76', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', $$Which protocol resolves hostnames to IP addresses?$$::text, $$[{"id": "A", "text": "DHCP", "is_correct": false}, {"id": "B", "text": "DNS", "is_correct": true}, {"id": "C", "text": "NTP", "is_correct": false}, {"id": "D", "text": "SNMP", "is_correct": false}]$$::jsonb, $$DNS resolves hostnames to IP addresses. DHCP assigns addresses, NTP synchronizes time, SNMP manages devices.$$::text, $${"https://www.juniper.net/us/en/training/certification/certification-tracks/jncip-ent.html"}$$::text[], $$Troubleshooting$$::text, 5.0, 'ff231e9d99cd77c1', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bfbfd41d-1f51-511e-bc0b-de382cb226be', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', $$Which command displays the system hostname?$$::text, $$[{"id": "A", "text": "show system hostname", "is_correct": false}, {"id": "B", "text": "show configuration system host-name", "is_correct": true}, {"id": "C", "text": "show host-name", "is_correct": false}, {"id": "D", "text": "show system name", "is_correct": false}]$$::jsonb, $$'show configuration system host-name' displays the configured hostname. 'show version' also shows it.$$::text, $${"https://www.juniper.net/us/en/training/certification/certification-tracks/jncip-ent.html"}$$::text[], $$Troubleshooting$$::text, 5.0, '0f5c335b21477a41', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9ca4f9fe-a24f-5152-8162-b12de3351c44', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', $$Which Junos command shows the current date and time?$$::text, $$[{"id": "A", "text": "show system uptime", "is_correct": true}, {"id": "B", "text": "show clock", "is_correct": false}, {"id": "C", "text": "show date", "is_correct": false}, {"id": "D", "text": "show time", "is_correct": false}]$$::jsonb, $$'show system uptime' shows current time, uptime, and users. Junos does not use 'show clock'.$$::text, $${"https://www.juniper.net/us/en/training/certification/certification-tracks/jncip-ent.html"}$$::text[], $$Troubleshooting$$::text, 5.0, '44eaeef1d2d4174a', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('84151f7f-0411-564a-a04c-178aa291fce3', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', $$Which logging severity level is the most critical?$$::text, $$[{"id": "A", "text": "Error", "is_correct": false}, {"id": "B", "text": "Critical", "is_correct": false}, {"id": "C", "text": "Alert", "is_correct": false}, {"id": "D", "text": "Emergency", "is_correct": true}]$$::jsonb, $$Syslog severity levels: Emergency (0), Alert, Critical, Error, Warning, Notice, Info, Debug (7).$$::text, $${"https://www.juniper.net/us/en/training/certification/certification-tracks/jncip-ent.html"}$$::text[], $$Troubleshooting$$::text, 5.0, '031c7a8bbc9a2ba5', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('21e5b332-1119-527d-91cf-173d2a3d2e3e', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', $$Which command shows the configured NTP servers?$$::text, $$[{"id": "A", "text": "show configuration system ntp", "is_correct": true}, {"id": "B", "text": "show ntp associations", "is_correct": false}, {"id": "C", "text": "show system ntp", "is_correct": false}, {"id": "D", "text": "show ntp status", "is_correct": false}]$$::jsonb, $$'show configuration system ntp' displays configured NTP servers. 'show ntp associations' shows active associations if ntpq is available.$$::text, $${"https://www.juniper.net/us/en/training/certification/certification-tracks/jncip-ent.html"}$$::text[], $$Troubleshooting$$::text, 5.0, 'a80ff7173b88553f', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e92f992a-c00b-54df-9915-c5811062cab8', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', $$Which feature logs every CLI command executed by users?$$::text, $$[{"id": "A", "text": "Syslog", "is_correct": false}, {"id": "B", "text": "Interactive-commands log", "is_correct": true}, {"id": "C", "text": "Audit log", "is_correct": false}, {"id": "D", "text": "Commit log", "is_correct": false}]$$::jsonb, $$Junos logs CLI commands to the interactive-commands log file for auditing.$$::text, $${"https://www.juniper.net/us/en/training/certification/certification-tracks/jncip-ent.html"}$$::text[], $$Troubleshooting$$::text, 5.0, '9d382363f256cd08', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('be4fc0f4-d5a8-58c8-b05d-37a73375873a', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', $$Which command displays the contents of a log file?$$::text, $$[{"id": "A", "text": "show log <filename>", "is_correct": true}, {"id": "B", "text": "file show <filename>", "is_correct": false}, {"id": "C", "text": "cat <filename>", "is_correct": false}, {"id": "D", "text": "display log <filename>", "is_correct": false}]$$::jsonb, $$'show log <filename>' displays log file contents. 'file show' displays arbitrary files.$$::text, $${"https://www.juniper.net/us/en/training/certification/certification-tracks/jncip-ent.html"}$$::text[], $$Troubleshooting$$::text, 5.0, '402e8ced65978001', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ece740e9-76f8-55da-b811-45788b7ead0a', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', $$Which command checks file system usage on the Routing Engine?$$::text, $$[{"id": "A", "text": "show system storage", "is_correct": true}, {"id": "B", "text": "show chassis fpc", "is_correct": false}, {"id": "C", "text": "show file system", "is_correct": false}, {"id": "D", "text": "show system filesystem", "is_correct": false}]$$::jsonb, $$'show system storage' displays disk usage on the RE.$$::text, $${"https://www.juniper.net/us/en/training/certification/certification-tracks/jncip-ent.html"}$$::text[], $$Troubleshooting$$::text, 5.0, '0daf316f14935e13', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('24f6458a-c6ae-52b1-a43b-1382bd037025', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', $$Which command displays the current software version?$$::text, $$[{"id": "A", "text": "show version", "is_correct": true}, {"id": "B", "text": "show system version", "is_correct": false}, {"id": "C", "text": "show software", "is_correct": false}, {"id": "D", "text": "show os version", "is_correct": false}]$$::jsonb, $$'show version' displays the Junos OS version, hardware model, and uptime.$$::text, $${"https://www.juniper.net/us/en/training/certification/certification-tracks/jncip-ent.html"}$$::text[], $$Troubleshooting$$::text, 5.0, '51cb4a1f73053591', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9a04b4c8-1070-52b7-ab06-6ade8718b24d', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', $$What is the broadcast address of 192.168.1.0/24?$$::text, $$[{"id": "A", "text": "192.168.1.255", "is_correct": true}, {"id": "B", "text": "192.168.1.254", "is_correct": false}, {"id": "C", "text": "192.168.1.0", "is_correct": false}, {"id": "D", "text": "192.168.255.255", "is_correct": false}]$$::jsonb, $$For 192.168.1.0/24, the broadcast address is 192.168.1.255.$$::text, $${"https://www.juniper.net/us/en/training/certification/certification-tracks/jncip-ent.html"}$$::text[], $$Subnetting$$::text, 5.0, '3499f2eb7e1c41c1', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('034adfbf-a55d-5f38-b187-8217a920657f', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', $$How many usable host addresses are in a /29 subnet?$$::text, $$[{"id": "A", "text": "6", "is_correct": true}, {"id": "B", "text": "8", "is_correct": false}, {"id": "C", "text": "4", "is_correct": false}, {"id": "D", "text": "2", "is_correct": false}]$$::jsonb, $$A /29 has 8 total addresses. Subtract network and broadcast for 6 usable hosts.$$::text, $${"https://www.juniper.net/us/en/training/certification/certification-tracks/jncip-ent.html"}$$::text[], $$Subnetting$$::text, 5.0, '4360b107a0a97888', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('355c91e4-23d9-550f-825d-fda4cb4a8c36', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', $$Which subnet mask corresponds to a /26 prefix?$$::text, $$[{"id": "A", "text": "255.255.255.192", "is_correct": true}, {"id": "B", "text": "255.255.255.224", "is_correct": false}, {"id": "C", "text": "255.255.255.128", "is_correct": false}, {"id": "D", "text": "255.255.255.240", "is_correct": false}]$$::jsonb, $$/26 = 255.255.255.192, providing 64 addresses per subnet.$$::text, $${"https://www.juniper.net/us/en/training/certification/certification-tracks/jncip-ent.html"}$$::text[], $$Subnetting$$::text, 5.0, '69b47d7c028da8d2', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7849ad7a-d281-5998-87b4-f3c8d79e5bcd', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', $$What is the first valid host in 10.0.0.0/30?$$::text, $$[{"id": "A", "text": "10.0.0.0", "is_correct": false}, {"id": "B", "text": "10.0.0.1", "is_correct": true}, {"id": "C", "text": "10.0.0.2", "is_correct": false}, {"id": "D", "text": "10.0.0.3", "is_correct": false}]$$::jsonb, $$10.0.0.0/30 has network 10.0.0.0 and broadcast 10.0.0.3. First host is 10.0.0.1.$$::text, $${"https://www.juniper.net/us/en/training/certification/certification-tracks/jncip-ent.html"}$$::text[], $$Subnetting$$::text, 5.0, '13927ad4fd97563a', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2c5c0696-dff5-5aa2-801f-cfddefb28882', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', $$Which VRRP state actively forwards traffic for the virtual IP?$$::text, $$[{"id": "A", "text": "Initialize", "is_correct": false}, {"id": "B", "text": "Backup", "is_correct": false}, {"id": "C", "text": "Master", "is_correct": true}, {"id": "D", "text": "Active", "is_correct": false}]$$::jsonb, $$In VRRP, the Master router forwards traffic for the virtual IP. Backup routers take over if Master fails.$$::text, $${"https://www.juniper.net/us/en/training/certification/certification-tracks/jncip-ent.html"}$$::text[], $$Layer 2 Switching$$::text, 12.0, 'c5844e081ea0fe0b', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4d0be7e6-bfd6-5160-8a30-e6826bd34ac7', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', $$Which command shows the aggregated Ethernet interface status on Junos?$$::text, $$[{"id": "A", "text": "show interfaces ae0 extensive", "is_correct": true}, {"id": "B", "text": "show ae0", "is_correct": false}, {"id": "C", "text": "show interface aggregate", "is_correct": false}, {"id": "D", "text": "show ethernet-switching ae0", "is_correct": false}]$$::jsonb, $$'show interfaces ae0 extensive' displays detailed status of aggregated Ethernet interfaces.$$::text, $${"https://www.juniper.net/us/en/training/certification/certification-tracks/jncip-ent.html"}$$::text[], $$Troubleshooting$$::text, 5.0, '388296f38adaa2de', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4f03bd01-6553-5b65-adf4-f2c8386324c2', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', $$Which feature prevents a switch port from learning too many MAC addresses?$$::text, $$[{"id": "A", "text": "BPDU Guard", "is_correct": false}, {"id": "B", "text": "Port security", "is_correct": true}, {"id": "C", "text": "Root Guard", "is_correct": false}, {"id": "D", "text": "Storm control", "is_correct": false}]$$::jsonb, $$Port security limits the number of MAC addresses on a port, preventing MAC flooding.$$::text, $${"https://www.juniper.net/us/en/training/certification/certification-tracks/jncip-ent.html"}$$::text[], $$Layer 2 Switching$$::text, 12.0, '57e402eb2351fec8', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('943047f9-10ab-5b24-ae32-ff03546f20f7', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', $$Which Junos command shows OSPF interface state?$$::text, $$[{"id": "A", "text": "show ospf interface", "is_correct": true}, {"id": "B", "text": "show ospf neighbor", "is_correct": false}, {"id": "C", "text": "show ospf database", "is_correct": false}, {"id": "D", "text": "show interface ospf", "is_correct": false}]$$::jsonb, $$'show ospf interface' displays OSPF-enabled interfaces, area, state, and DR/BDR info.$$::text, $${"https://www.juniper.net/us/en/training/certification/certification-tracks/jncip-ent.html"}$$::text[], $$Troubleshooting$$::text, 5.0, '6cc83ab9cea0d9e9', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('590c10b6-6034-5090-a7fc-a66ee7cd687a', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', $$Which command verifies IS-IS adjacency state?$$::text, $$[{"id": "A", "text": "show isis adjacency", "is_correct": true}, {"id": "B", "text": "show isis neighbor", "is_correct": false}, {"id": "C", "text": "show isis interface", "is_correct": false}, {"id": "D", "text": "show isis database", "is_correct": false}]$$::jsonb, $$'show isis adjacency' displays IS-IS neighbors and their states.$$::text, $${"https://www.juniper.net/us/en/training/certification/certification-tracks/jncip-ent.html"}$$::text[], $$Troubleshooting$$::text, 5.0, '8ac61b50bdc904b1', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('715d225a-bca9-5a64-854c-b682719e2fff', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', $$Which command shows the BGP routing information base?$$::text, $$[{"id": "A", "text": "show bgp summary", "is_correct": false}, {"id": "B", "text": "show route protocol bgp", "is_correct": true}, {"id": "C", "text": "show bgp database", "is_correct": false}, {"id": "D", "text": "show route table bgp", "is_correct": false}]$$::jsonb, $$'show route protocol bgp' displays routes learned via BGP in the routing table.$$::text, $${"https://www.juniper.net/us/en/training/certification/certification-tracks/jncip-ent.html"}$$::text[], $$Troubleshooting$$::text, 5.0, '2e91856f0de2f57e', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('78122239-22a9-5753-91e4-16f5fd6b0185', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', $$Which protocol is used for link-state routing in large enterprise networks?$$::text, $$[{"id": "A", "text": "RIP", "is_correct": false}, {"id": "B", "text": "OSPF", "is_correct": true}, {"id": "C", "text": "BGP", "is_correct": false}, {"id": "D", "text": "Static routing", "is_correct": false}]$$::jsonb, $$OSPF is a link-state IGP commonly used in large enterprise networks.$$::text, $${"https://www.juniper.net/us/en/training/certification/certification-tracks/jncip-ent.html"}$$::text[], $$OSPF$$::text, 12.0, '705671b68696bac1', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('837908c1-9c9d-5296-b3ea-bb356d657a5c', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', $$Which command displays the forwarding table on Junos?$$::text, $$[{"id": "A", "text": "show route forwarding-table", "is_correct": true}, {"id": "B", "text": "show forwarding-table", "is_correct": false}, {"id": "C", "text": "show route table", "is_correct": false}, {"id": "D", "text": "show fpc forwarding", "is_correct": false}]$$::jsonb, $$'show route forwarding-table' displays the forwarding table used by the PFE.$$::text, $${"https://www.juniper.net/us/en/training/certification/certification-tracks/jncip-ent.html"}$$::text[], $$Troubleshooting$$::text, 5.0, '25c8d67975d32278', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9c2877a0-0b40-5cf5-afd0-b5cc85fb3f5c', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', $$Which Junos configuration mode command shows only the changes made in the current session?$$::text, $$[{"id": "A", "text": "show | compare", "is_correct": true}, {"id": "B", "text": "show diff", "is_correct": false}, {"id": "C", "text": "show changes", "is_correct": false}, {"id": "D", "text": "show configuration | display set", "is_correct": false}]$$::jsonb, $$'show | compare' in configuration mode shows the diff between candidate and active configurations.$$::text, $${"https://www.juniper.net/us/en/training/certification/certification-tracks/jncip-ent.html"}$$::text[], $$Troubleshooting$$::text, 5.0, '909fbf5689179c26', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('da287727-37b2-582b-97d7-e7cd9c74e5bd', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', $$Which command loads a previously saved rescue configuration?$$::text, $$[{"id": "A", "text": "load rescue", "is_correct": true}, {"id": "B", "text": "rollback rescue", "is_correct": false}, {"id": "C", "text": "commit rescue", "is_correct": false}, {"id": "D", "text": "request rescue", "is_correct": false}]$$::jsonb, $$'load rescue' loads the saved rescue configuration into the candidate config.$$::text, $${"https://www.juniper.net/us/en/training/certification/certification-tracks/jncip-ent.html"}$$::text[], $$Troubleshooting$$::text, 5.0, 'a89fb4d9ff6a9dc9', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6687697a-4950-5deb-b9a5-75353b333893', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', $$Which feature allows a Junos device to archive configurations automatically?$$::text, $$[{"id": "A", "text": "Configuration archival", "is_correct": true}, {"id": "B", "text": "Rescue config", "is_correct": false}, {"id": "C", "text": "Commit scripts", "is_correct": false}, {"id": "D", "text": "Rollback", "is_correct": false}]$$::jsonb, $$Configuration archival automatically saves configurations to remote servers at defined intervals.$$::text, $${"https://www.juniper.net/us/en/training/certification/certification-tracks/jncip-ent.html"}$$::text[], $$Troubleshooting$$::text, 5.0, '3fb770de1fe2a6c9', true) ON CONFLICT (id) DO NOTHING;
